      el('extImageUpdatePlanBtn').disabled=true;
      el('extImageUpdateApplyBtn').disabled=true;
      el('extImageUpdatePlan').textContent=(task.status==='interrupted'?i18nText('extensions.update_image_failed'):i18nText('extensions.update_image_started'))+' '+Number(task.progress||0)+'%';
