  // The service-card renderer historically embedded opaque handles in inline
  // handlers. Quotes in those handles can truncate the attribute and leave
  // the visible update/reset buttons inert. Rebind both actions from the
  // card's data attribute after each render and stop the broken inline call.
  var extRenderServiceGroupsWithSafeActions=extRenderServiceGroups;
  function extWireManagedServiceActions(container){
    if(!container)return;
    container.querySelectorAll('button[onclick^="extensionOpenExistingPushSource"],button[onclick^="extensionOpenImageUpdateModal"],button[onclick^="extensionOpenResetModal"]').forEach(function(button){
      var card=button.closest('.ext-service-card[data-instance-handle]'),handle=card&&card.dataset&&card.dataset.instanceHandle;
      if(!handle)return;
      var action=button.getAttribute('onclick')||'';
      button.removeAttribute('onclick');
      button.addEventListener('click',function(event){
        event.preventDefault();
        event.stopImmediatePropagation();
        if(action.indexOf('extensionOpenExistingPushSource')===0)window.extensionOpenExistingPushSource(handle);
        else if(action.indexOf('extensionOpenImageUpdateModal')===0)window.extensionOpenImageUpdateModal(handle);
        else window.extensionOpenResetModal(handle);
      },true);
    });
  }
